// Build Full 180 Questions for NEET UG 2024
const full180Questions = [];

// Helper to push formatted question
function addQuestion(bankArray, list, subject, startIdx, testId) {
  list.forEach((item, i) => {
    const qNum = startIdx + i;
    const formatted = {
      id: `${testId}-Q${qNum}`,
      testId: testId,
      exam: "NEET-UG",
      subject: subject,
      qNumber: qNum,
      year: 2024,
      difficulty: "Moderate",
      question: `Q${qNum}. [${item.topic}] ${item.q}`,
      options: [
        { id: "A", text: item.opts[0] },
        { id: "B", text: item.opts[1] },
        { id: "C", text: item.opts[2] },
        { id: "D", text: item.opts[3] }
      ],
      correct: item.ans,
      explanation: item.exp,
      ncertRef: item.ref
    };
    bankArray.push(formatted);
  });
}

// 1. Physics: Q1 to Q45
addQuestion(full180Questions, physicsTopics, "Physics", 1, "NEET-2024-FULL");

// 2. Chemistry: Q46 to Q90
addQuestion(full180Questions, chemTopics, "Chemistry", 46, "NEET-2024-FULL");

// 3. Botany: Q91 to Q135
addQuestion(full180Questions, botanyTopics, "Botany", 91, "NEET-2024-FULL");

// 4. Zoology: Q136 to Q180
addQuestion(full180Questions, zoologyTopics, "Zoology", 136, "NEET-2024-FULL");

console.log(`Generated ${full180Questions.length} questions for NEET-2024-FULL!`);

// Deduplicate existing bank and append full 180 paper
const existingIds = new Set(existingBank.map(q => q.id));
let added = 0;
for (const q of full180Questions) {
  if (!existingIds.has(q.id)) {
    existingBank.push(q);
    existingIds.add(q.id);
    added++;
  }
}

fs.writeFileSync(bankPath, JSON.stringify(existingBank, null, 2), 'utf8');
fs.writeFileSync(publicBankPath, JSON.stringify(existingBank, null, 2), 'utf8');
console.log(`Successfully updated questions bank! Total questions in database: ${existingBank.length} (Added ${added})`);

